package com.oracle.banking.twofa.controller;
import com.oracle.banking.shared.response.ApiResponse; import com.oracle.banking.twofa.dto.TwoFactorDtos.*; import com.oracle.banking.twofa.service.TwoFactorService; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/2fa") public class TwoFactorController { private final TwoFactorService service; public TwoFactorController(TwoFactorService s){service=s;} @PostMapping("/setup") ApiResponse<SetupResponse> setup(Authentication a){return ApiResponse.success("2FA setup created",service.setup(a.getName()));} @PostMapping("/verify-setup") ApiResponse<StatusResponse> verifySetup(Authentication a,@Valid @RequestBody VerifyRequest r){return ApiResponse.success("2FA enabled",service.verifySetup(a.getName(),r.otpCode()));} @PostMapping("/verify") ApiResponse<StatusResponse> verify(Authentication a,@Valid @RequestBody VerifyRequest r){return ApiResponse.success("OTP verified",service.verify(a.getName(),r.otpCode()));} @PostMapping("/disable") ApiResponse<StatusResponse> disable(Authentication a,@Valid @RequestBody VerifyRequest r){return ApiResponse.success("2FA disabled",service.disable(a.getName(),r.otpCode()));} @GetMapping("/status") ApiResponse<StatusResponse> status(Authentication a){return ApiResponse.success("2FA status",service.status(a.getName()));} }
